#!/usr/bin/env node
// Renders the "Step Processors" rows of docs/EDITIONS.md from the served processor catalog's committed
// contract (inspecto-ui/src/app/inspecto/contracts/processor-catalog.contract.json — regenerated by the
// Java ProcessorCatalogContractTest with -Dprocessor.catalog.write=true). ONE list, two renderings: the
// palette reads the catalog, the board reads this. Edit ProcessorCatalog.java, regenerate the contract,
// run this; never hand-edit an `| SP-` row.
//
//   node tools/render-processor-board.mjs            # rewrite the rows in place
//   node tools/render-processor-board.mjs --check    # exit 1 when the board is stale (CI-friendly)
//
// Edition cells: the status glyph in all three editions, except the board decisions recorded below
// (kept here, in code, so a regeneration cannot silently forget them).
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const CONTRACT = join(root, 'inspecto-ui/src/app/inspecto/contracts/processor-catalog.contract.json');
const BOARD = join(root, 'docs/EDITIONS.md');

// Operator decisions 2026-09-02 (EDITIONS.md §Feature × edition matrix): not for Personal / Enterprise-only.
const NOT_FOR_PERSONAL = new Set([
    'control.alert.dispatch', 'sink.notify.email', 'sink.api.webhook', 'quality.pii.mask',
    'quality.compliance.redact', 'transform.geo.h3', 'transform.geo.spatial_join',
    'enrichment.graph.cluster', 'sink.archive',
]);
const ENTERPRISE_ONLY = new Set(['quality.pii.mask', 'quality.compliance.redact']);
const GLYPH = { delivered: '✅', partial: '🟡', planned: '🔲' };

const catalog = JSON.parse(readFileSync(CONTRACT, 'utf8'));
const familyLabel = Object.fromEntries(catalog.families.map((f) => [f.code, f.label]));
const counters = {};
const rows = catalog.processors.map((p) => {
    counters[p.family] = (counters[p.family] ?? 0) + 1;
    const id = `SP-${p.family}-${String(counters[p.family]).padStart(2, '0')}`;
    const g = GLYPH[p.status];
    const P = NOT_FOR_PERSONAL.has(p.id) ? '—' : g;
    const S = ENTERPRISE_ONLY.has(p.id) ? '—' : g;
    const maps = p.nodeType ?? p.capability;
    return `| ${id} | ${p.emoji} ${p.label} (\`${p.id}\`) | ${familyLabel[p.family]} | ${P} | ${S} | ${g} | ${maps ? '`' + maps + '`' : '—'} | ${p.note ?? ''} |`;
});
const n = catalog.processors.length;
const delivered = catalog.processors.filter((p) => p.status === 'delivered').length;
const partial = catalog.processors.filter((p) => p.status === 'partial').length;
const countLine = `**Count:** ${n} processors — ${delivered} delivered, ${partial} partial, ${n - delivered - partial} planned.`;

const board = readFileSync(BOARD, 'utf8');
const lines = board.split('\n');
const kept = lines.filter((l) => !l.startsWith('| SP-') && !l.startsWith('**Count:** '));
const header = kept.findIndex((l) => l.startsWith('|---|---|---|---|---|---|---|---|'));
if (header < 0) {
    console.error('✖ render-processor-board: the Step Processors table header was not found in docs/EDITIONS.md');
    process.exit(2);
}
kept.splice(header + 1, 0, ...rows);
// the count line sits after the table's trailing blank line: rows, '', count, '', next section
const after = header + 1 + rows.length;
if (kept[after] !== '') kept.splice(after, 0, '');
while (kept[after + 1] === '') kept.splice(after + 1, 1);
kept.splice(after + 1, 0, countLine, '');
const next = kept.join('\n');

if (process.argv.includes('--check')) {
    if (next !== board) {
        console.error('✖ docs/EDITIONS.md Step Processors table is STALE against processor-catalog.contract.json — run node tools/render-processor-board.mjs');
        process.exit(1);
    }
    console.log(`✓ Step Processors board is current (${n} rows).`);
} else {
    writeFileSync(BOARD, next);
    console.log(`✓ Step Processors board rendered: ${n} rows (${delivered} delivered, ${partial} partial).`);
}
